// 胸像点云：seedream-5.0 生成的白色大理石女性胸像图，按明暗对比采样（已去掉水印区），用于星系页。
// window.BUST_POINTS = {count, stride:4, data: Float32Array}，每 4 个数一组 [x, y, z, lum]：
// x/y 约在 [-1,1]（y 向下，胸像外接框中心为原点，头顶约 y=-1，胸像底边约 y=+1），z = 伪深度 0..1（轮廓内部更大，可当作朝向观者的凸起），lum = 明暗 0..1（亮处点更密更亮）。
(function(){var b=atob('');var n=36000,u=new Uint8Array(b.length);for(var i=0;i<b.length;i++)u[i]=b.charCodeAt(i);var d=new Float32Array(n*4);for(var k=0;k<n;k++){var o=k*6;d[k*4]=(u[o]|u[o+1]<<8)/65535*2.4-1.2;d[k*4+1]=(u[o+2]|u[o+3]<<8)/65535*2.4-1.2;d[k*4+2]=u[o+4]/255;d[k*4+3]=u[o+5]/255;}window.BUST_POINTS={count:n,stride:4,data:d};})();
